export type InterpolationGridSize = { label?: string; cols: number; rows: number };
export type InterpolationLayer = {
    id: string;
    name: string;
    type: 'terrain' | 'water_table' | 'contamination' | 'geology' | 'custom' | string;
    visible: boolean;
    method?: string;
    gridSize: { cols: number; rows: number };
    colorRamp?: string;
    stats?: { min: number; max: number; mean: number };
    opacity?: number;
    fixedColor?: string;
    parameterId?: string;
    wireframe?: boolean;
    mesh?: unknown;
    showContours?: boolean;
    contourDensity?: string;
    showContourLabels?: boolean;
    thresholdValue?: number | null;
    satelliteUrls?: string[];
    textureMode?: string;
};
export type SoilTypeAvailability = { soilType: string; count: number };

export const GRID_SIZES: InterpolationGridSize[];
export function initInterpolation(...args: unknown[]): unknown;
export function setInterpolationGroup(...args: unknown[]): unknown;
export function setInterpolationUpdateAllUI(...args: unknown[]): unknown;
export function addLayer(...args: unknown[]): unknown;
export function removeLayer(...args: unknown[]): unknown;
export function clearAllLayers(...args: unknown[]): unknown;
export function updateLayer(...args: unknown[]): unknown;
export function getLayer(id: string): InterpolationLayer | null;
export function getAllLayers(...args: unknown[]): InterpolationLayer[];
export function getLayerMesh(...args: unknown[]): unknown;
export function getInterpolationGroup(...args: unknown[]): { children: any[] } | null;
export function getSelectedLayer(...args: unknown[]): string | null;
export function setSelectedLayer(...args: unknown[]): unknown;
export function createTerrainLayer(...args: unknown[]): Promise<InterpolationLayer>;
export function createWaterTableLayer(...args: unknown[]): Promise<InterpolationLayer>;
export function createContaminationLayer(...args: unknown[]): Promise<InterpolationLayer>;
export function createGeologyLayer(...args: unknown[]): Promise<InterpolationLayer>;
